# 13_data_people.py -- the cast of the Thallen March (12.11.1 depths; 15.2.1 social record): principal and
# recurring NPCs with roles, homes, memberships, wants (ranked), fears, refusals (15's refusal kinds), sealed
# secrets with gates, knowledge, voice, lifestyle and tongues; plus bond-placement rules (02.9.2).
# Read by 13-gen_region.py.

def N(id, name, role, people, gender, age, depth, home, member_of, wants, fear, refusals, secrets=(), knowledge=(),
      register="plain", habit="", detail="", demeanor="", lifestyle="modest", speaks=("lic.lang.common",), band=None,
      standing=0, exists="exists", notes="", officer_duty=None, recruit=None):
    pron = {"woman": "she/her", "man": "he/him"}[gender]
    return dict(id=id, name=name, role=role, people=people, gender=gender, pronouns=pron, age=age, depth=depth, home=home,
                member_of=list(member_of), wants=[dict(text=w[0], tags=list(w[1]), rank=i + 1) for i, w in enumerate(wants)],
                fears=[dict(text=fear[0], tags=list(fear[1]))], refusals=[dict(kind=r[0], text=r[1]) for r in refusals],
                secrets=[dict(fact=s[0], text=s[1], gate=s[2]) for s in secrets], knowledge=list(knowledge),
                voice=dict(register=register, habit=habit), detail=detail, demeanor=demeanor, lifestyle=lifestyle,
                speaks=list(speaks), band=band, standing_to_pc=standing, exists=exists, notes=notes, officer_duty=officer_duty,
                recruit=recruit)

